#!/usr/bin/env node
/**
 * scripts/build-console-bundle.mjs
 *
 * Builds the single-file innfo-console bundle from the console package's UMD
 * sources. Concatenates them in dependency order — each source is a self-contained
 * IIFE/UMD that auto-boots only when its own DOM anchors exist, so concatenation
 * is safe and exactly one renderer boots per shell.
 *
 * Order:
 *   1. uplot.iife.min.js      (vendored uPlot v1.6.31 — charts capability)
 *   2. visuals.js             (InnfoVisuals — no boot, pure vocabulary)
 *   3. innfo-runtime.js       (InnfoConsole — boots on #innfo-config)
 *   4. render-model-viewer.js (InnfoModelViewer — boots on #doc-title + #rail)
 *   5. render-procedure-stepper.js (InnfoProcedureStepper — boots on #doc-title + #proc-tabs)
 *
 * Output: iNNfo/specs/templates/console/innfo-console.bundle.js (committed,
 * following the innfo-mcp.bundle.js precedent). Regenerate on every console release.
 */

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const consoleDir = join(here, '..', 'iNNfo', 'specs', 'templates', 'console')

const SOURCES = [
  ['uplot.iife.min.js', 'uPlot'],
  ['visuals.js', 'InnfoVisuals'],
  ['innfo-runtime.js', 'InnfoConsole'],
  ['render-model-viewer.js', 'InnfoModelViewer'],
  ['render-procedure-stepper.js', 'InnfoProcedureStepper'],
]

const BUNDLE_VERSION = '0.1.0'
const OUT = join(consoleDir, 'innfo-console.bundle.js')

const header = `/*!
 * innfo-console.bundle.js — single-file console runtime + renderers.
 * Generated by scripts/build-console-bundle.mjs — DO NOT EDIT BY HAND.
 * Version ${BUNDLE_VERSION}. Regenerate on every console release.
 * Composed (in dependency order): ${SOURCES.map(([f]) => f).join(', ')}.
 */
`

const parts = [header]
for (const [file, globalName] of SOURCES) {
  const src = readFileSync(join(consoleDir, file), 'utf8')
  parts.push(`/* ===== ${file} (defines ${globalName}) ===== */\n` + src.trim() + '\n')
}

mkdirSync(dirname(OUT), { recursive: true })
writeFileSync(OUT, parts.join('\n'))
console.log(`wrote ${OUT} (${SOURCES.length} sources, version ${BUNDLE_VERSION})`)